mapper.select:
SELECT
WHERE r.deleted = 0 AND s.deleted = 0 AND a.deleted = 0
AND a.org_id = #{scopeOrgId}
AND (u.real_name ILIKE CONCAT('%', #{q.keyword}, '%') OR si.student_no ILIKE CONCAT('%', #{q.keyword}, '%') OR a.title ILIKE CONCAT('%', #{q.keyword}, '%'))
AND s.activity_id = #{q.activityId}
AND s.student_id = #{q.studentId}
AND (r.status = 'ABSENT' OR (r.status = 'NOT_SIGNED' AND a.end_time IS NOT NULL AND a.end_time + INTERVAL '30 minutes' < #{now}))
AND r.status = 'NOT_SIGNED' AND (a.end_time IS NULL OR a.end_time + INTERVAL '30 minutes' >= #{now})
AND r.status = #{q.status}
ORDER BY r.id DESC
